/* =====================================================================================
   RECALL - flashcards with spaced repetition. p0pc0rn skeleton "flashcards-learn".
   Serves: Education (vocabulary, language learning, exam prep), Reference (facts, capitals,
           code cheat-sheets), Books (reading notes, quotes, literary terms).

   SCREENS
     decks    large title that collapses on scroll, a TODAY card (goal ring, cards ready, streak,
              Study button), one card per deck with a progress bar + due chip, a THIS WEEK bar
              chart, and a settings sheet (sound, daily goal, session size, reset).
     study    a stack of index cards: 2 wait behind the top one (offset + scale). Tap = flip
              (a 3D-looking scale-x turn: the card lifts and its shadow spreads). Swipe right =
              know, left = again: the card flies off with rotation and the next rises from the
              stack. Show answer -> Again / Good / Easy buttons with the next interval above each.
     summary  accuracy ring, reviewed / time / next review, answers per grade (K.bars), a streak
              card with a 7-day strip, Keep studying / Done.
   STATES: loading skeleton (first 0.8 s while fetchLive runs), sync error banner, empty deck
   ("All caught up" + a 7-day COMING UP forecast + Study ahead), win (confetti at >= 60 % first-try
   accuracy), tough session (softer copy), streak +1 celebration, partial session ("Session saved").

   TO MAKE A NEW APP FROM THIS FILE
     - REPLACE the SAMPLE DATA block: DECKS (name, side labels, hue, icon, cards [front, back, note]).
       Book quotes: front = the quote, back = book + author. Vocabulary: front = the word.
     - REPLACE APP_NAME, the palette constants and the starting history in seedProgress / seedStats.
     - KEEP the SPACED REPETITION section (nextIvl / schedule), the STACK section (slots, drag,
       fly-off, flip) and the persistence helpers: they work for any deck of cards.
   ===================================================================================== */

// ===== THEME + LAYOUT =====
const APP_NAME = String((window.SLOTS && window.SLOTS.app_name) || 'Recall').slice(0, 22);                   // REPLACE: the app's name (the large title)
const INK = (window.SLOTS && window.SLOTS.accent) || '#274b9f';                       // accent: fountain-pen ink blue
const PAPER = '#fffdf7';                     // index-card stock (every card surface)
const PAPER_BACK = '#efe6d6';                // the cards waiting in the stack are a shade darker
const RULE = '#b8c9ea';                      // the blue ruled lines on a card
const MARGIN_RED = '#e0766c';                // the red header line every index card has
const AGAIN_COL = '#cf4a3f', GOOD_COL = '#2e8b57', EASY_COL = INK;
const FLAME = '#ee8a2b';                     // streaks
const SHADOW_INK = '#3b2c14';                // warm shadow on paper (never pure black)
const SIDE = 16;                             // screen margin
const CARD_R = 18, RULE_GAP = 34;
const TODAY_H = 200, DECK_H = 96, WEEK_H = 172, SHEET_H = 372;
const SLOT_DROP = 14, SLOT_SCALE = 0.05;     // each waiting card sits 14 px lower and 5 % smaller
const SESSION_SIZE = Math.max(3, Math.min(30, Math.round(+((window.SLOTS || {}).session_size) || 8)));                      // REPLACE: cards per session (settings can change it)
const REQUEUE_GAP = 3;                       // an "again" card comes back after 3 other cards
const WIN_AT = 0.6;                          // first-try accuracy that counts as a great session
const LOAD_S = 0.8;                          // minimum time the loading skeleton shows
const MIN_MS = 60000, HOUR_MS = 3600000, DAY_MS = 86400000;
const KEY = 'recall.v1.';                    // storage prefix: bump it when the saved shape changes

// ===== SAMPLE DATA (REPLACE for a new app) =====
// sides = the small label on the front and on the back. mono = the answer is code (monospaced).
// Each card is [front, back, note]; the note sits under the answer (example, fact, tip).
const DEF_DECKS = [
  { id: 'es', name: 'Spanish Basics', sides: ['SPANISH', 'ENGLISH'], icon: 'chat', hue: '#d45a3c', cards: [
    ['hola', 'hello', '¡Hola! ¿Qué tal?'], ['gracias', 'thank you', 'Muchas gracias por todo.'],
    ['por favor', 'please', 'Un café, por favor.'], ['el agua', 'water', 'Un vaso de agua, por favor.'],
    ['la casa', 'house', 'Mi casa es tu casa.'], ['el perro', 'dog', 'El perro duerme en el sofá.'],
    ['el gato', 'cat', 'El gato es negro.'], ['la mañana', 'morning', 'Corro por la mañana.'],
    ['la noche', 'night', 'Buenas noches, mamá.'], ['el libro', 'book', 'Leo un libro nuevo.'],
    ['la manzana', 'apple', 'Una manzana roja, por favor.'], ['el pan', 'bread', 'El pan está caliente.'],
    ['el amigo', 'friend', 'Mi amigo vive en Madrid.'], ['la ciudad', 'city', 'La ciudad nunca duerme.'],
    ['el tren', 'train', 'El tren sale a las ocho.'], ['hoy', 'today', 'Hoy hace sol.'],
    ['mañana', 'tomorrow', 'Nos vemos mañana.'], ['siempre', 'always', 'Siempre llega tarde.'],
    ['¿dónde está?', 'where is it?', '¿Dónde está la estación?'], ['¿cuánto cuesta?', 'how much is it?', '¿Cuánto cuesta el billete?']] },
  { id: 'cap', name: 'Capitals', sides: ['CAPITAL OF', 'CAPITAL'], icon: 'globe', hue: '#2a8c7e', cards: [
    ['France', 'Paris', 'On the Seine, 2.1 million people'], ['Japan', 'Tokyo', 'The largest metro area on Earth'],
    ['Canada', 'Ottawa', 'Not Toronto: chosen in 1857'], ['Australia', 'Canberra', 'Purpose-built, opened in 1927'],
    ['Brazil', 'Brasília', 'Built in 41 months, opened 1960'], ['Kenya', 'Nairobi', 'Has a national park inside the city'],
    ['Egypt', 'Cairo', 'At the head of the Nile delta'], ['Peru', 'Lima', 'Founded in 1535 on the Pacific'],
    ['Norway', 'Oslo', 'At the head of the Oslofjord'], ['Vietnam', 'Hanoi', 'On the banks of the Red River'],
    ['Mexico', 'Mexico City', 'Built on the bed of Lake Texcoco'], ['Turkey', 'Ankara', 'Not Istanbul: capital since 1923'],
    ['Argentina', 'Buenos Aires', 'On the Río de la Plata'], ['New Zealand', 'Wellington', 'The southernmost national capital'],
    ['Morocco', 'Rabat', 'On the Atlantic coast']] },
  { id: 'p5', name: 'p5.js functions', sides: ['WHICH FUNCTION?', 'P5.JS'], mono: true, icon: 'edit', hue: '#c93a6e', cards: [
    ['Draw an ellipse', 'ellipse(x, y, w, h)', 'Centred on x, y by default'],
    ['Re-map a number from one range to another', 'map(v, a1, b1, a2, b2)', 'Pass true at the end to clamp'],
    ['Blend between two numbers', 'lerp(a, b, t)', 't = 0 gives a, t = 1 gives b'],
    ['Keep a value inside limits', 'constrain(v, lo, hi)', 'Great for paddles and sliders'],
    ['Save and restore drawing state', 'push() / pop()', 'Wrap every translate and rotate'],
    ['Move the origin', 'translate(x, y)', 'Adds up until the next pop()'],
    ['Smooth random values', 'noise(x)', 'Perlin noise between 0 and 1'],
    ['A random number in a range', 'random(lo, hi)', 'random(list) picks an item'],
    ['Milliseconds since the sketch started', 'millis()', 'Timers that ignore the frame rate'],
    ['Make the drawing surface', 'createCanvas(w, h)', 'Call it once, in setup()'],
    ['Set the fill colour', 'fill(r, g, b, a)', 'Numbers, or one hex string'],
    ['Turn what comes next', 'rotate(angle)', 'Radians unless angleMode says otherwise']] }
];
const okIcon = (n, d) => (typeof n === 'string' && (!K.ICONS || K.ICONS.includes(n)) ? n : d);
// ----- slots -----
const SL = window.SLOTS || {};
const cardOf = (c) => Array.isArray(c) ? [String(c[0] ?? ''), String(c[1] ?? ''), String(c[2] ?? '')] : [String(c.front ?? ''), String(c.back ?? ''), String(c.note ?? '')];
const DECKS = Array.isArray(SL.decks) && SL.decks.length ? SL.decks.slice(0, 6).map((d, i) => ({ id: 'd' + i, name: String(d.name || 'Deck ' + (i + 1)).slice(0, 26),
  sides: Array.isArray(d.sides) && d.sides.length >= 2 ? [String(d.sides[0]).slice(0, 16).toUpperCase(), String(d.sides[1]).slice(0, 16).toUpperCase()] : ['FRONT', 'BACK'],
  mono: !!d.mono, icon: okIcon(d.icon, 'book'), hue: d.hue || d.color || '#2a8c7e',
  cards: (Array.isArray(d.cards) ? d.cards : []).map(cardOf).filter((c) => c[0] && c[1]).slice(0, 60) })).filter((d) => d.cards.length) : DEF_DECKS;
if (!DECKS.length) DECKS.push(...DEF_DECKS);
const GRADES = [{ id: 'again', label: 'Again', col: AGAIN_COL }, { id: 'good', label: 'Good', col: GOOD_COL },
  { id: 'easy', label: 'Easy', col: EASY_COL }];

// ===== STATE + PERSISTENCE =====
let progress = {}, stats = {}, prefs = {};   // saved: per-card schedule, streak + daily counts, settings
let sum = null;                              // the finished session shown on the summary screen
// Runtime-only UI state (never saved: it holds K.t times that mean nothing after a reload).
const ui = { readyAt: LOAD_S, syncError: false, scrollY: 0, sheet: false, resetArmed: 0,
  dragId: null, dragVx: 0, flipAt: -9, frontAt: -9, dealAt: 0, flipTw: null, shiftTw: null, flamePos: null, pill: null, streakPopAt: 0 };
const study = { deck: DECKS[0], queue: [], total: 0, done: 0, first: {}, counts: {}, t0: 0,
  flipped: false, busy: false, empty: false, lastGrade: null };
// The top card's motion. Tweens (flip, fly-off, rise) and the finger (drag) both write these numbers.
const fx = { flip: 0, x: 0, y: 0, rot: 0, shift: 0 };
const flameSpring = K.spring(1, { k: 260, d: 9 });    // kicked when the streak grows

function loadAll() {
  progress = K.load(KEY + 'progress', null) || seedProgress();
  stats = K.load(KEY + 'stats', null) || seedStats();
  prefs = Object.assign({ sound: true, goal: 20, size: SESSION_SIZE }, K.load(KEY + 'prefs', {}));
  K.sound = prefs.sound;
}
function saveAll() { K.save(KEY + 'progress', progress); K.save(KEY + 'stats', stats); K.save(KEY + 'prefs', prefs); }

// REPLACE: the history a first-time user sees. Spanish is half learned (5 due now), Capitals is
// fully learned (nothing due: shows the "All caught up" state), p5.js is brand new.
function seedProgress() { return {}; }   // a new app starts with no history
function rec(ivl, due) { return { ivl, ease: 2.5, due, reps: 1 + Math.round(ivl / 4), lapses: 0 }; }
function seedStats() { return { streak: 0, best: 0, last: '', days: {} }; }

// LIVE DATA seam: a synced app would pull shared decks here. Called from setup() and the Retry button.
async function fetchLive() { /* no live source in this skeleton: the cards come from the slots */ return null; }
function syncDecks() {
  ui.readyAt = K.t + LOAD_S; ui.syncError = false;
  fetchLive().then((data) => {
    if (Array.isArray(data)) data.forEach((d) => { if (d && d.id && d.cards && !DECKS.some((o) => o.id === d.id)) DECKS.push(d); });
  }).catch(() => { ui.syncError = true; K.toast('Could not sync decks', { tone: 'warn', icon: 'cloud' }); });
}

// ===== SMALL HELPERS =====
function cardId(deck, i) { return deck.id + ':' + i; }
function prog(deck, i) { return progress[cardId(deck, i)] || null; }
function clamp01(v) { return Math.max(0, Math.min(1, v)); }
function dayKey(offset) { const d = new Date(Date.now() + (offset || 0) * DAY_MS); return d.getFullYear() + '-' + (d.getMonth() + 1) + '-' + d.getDate(); }
function dayLetter(offset) { return 'SMTWTFS'[new Date(Date.now() + offset * DAY_MS).getDay()]; }
function after(ms, fn) { K.tween({ v: 0 }, { v: 1 }, ms, { onDone: fn, scene: true }); }   // a tween timer; dies if you leave the screen
function plural(n, word) { return n + ' ' + word + (n === 1 ? '' : 's'); }     // 1 card, 2 cards
function fmtSpan(secs) { return secs < 60 ? Math.max(1, Math.floor(secs)) + ' s' : Math.round(secs / 60) + ' min'; }   // floor: matches K.fmt.clock
function fmtIvl(days) { if (days < 1) return '1 min'; if (days < 31) return days + ' d'; if (days < 365) return Math.round(days / 30) + ' mo'; return (days / 365).toFixed(1) + ' y'; }
function fmtDue(ts) {
  const ms = ts - Date.now();
  if (!isFinite(ms) || ms <= 0) return 'now';
  if (ms < HOUR_MS) return 'in ' + Math.ceil(ms / MIN_MS) + ' min';
  if (ms < DAY_MS) return 'in ' + Math.round(ms / HOUR_MS) + ' h';
  const d = Math.round(ms / DAY_MS); return d === 1 ? 'tomorrow' : 'in ' + d + ' days';
}
// Fades a group of plain drawing (cards, text, rings, charts) for an entrance: kit drawing multiplies the context alpha.
// Kit CONTROLS never go in here or in your own translate(): they take { alpha } and their real screen y.
function withAlpha(a, fn) { K.with((c) => { c.globalAlpha *= clamp01(a); fn(); }); }
// Entrances: K.stagger(i, 55, 440) on every screen. The home screen's blocks wait for the loading skeleton,
// so they start from whichever came later: the screen opening or the skeleton giving way (K.since).
function homeIn(i) { return K.since(Math.max(ui.readyAt, K.t - K.sceneAge()), i * 55, 440); }
function rise(e) { return 18 * (1 - e); }
function paperBackdrop() {
  K.backdrop({ top: '#fbf7ef', bottom: '#eee4d3', vignette: 0.08, grain: 0.06, glow: [
    { x: K.W * 0.92, y: K.safe.top + 30, r: 340, color: INK, s: 0.08 }, { x: 0, y: K.H * 0.82, r: 300, color: MARGIN_RED, s: 0.06 }] });
}

// ===== SPACED REPETITION (a small SM-2: interval grows by the card's ease) =====
const NEW_REC = { ivl: 0, ease: 2.5, due: 0, reps: 0, lapses: 0 };
function nextIvl(p, grade) {
  if (grade === 'again') return 0;
  if (p.ivl < 1) return grade === 'easy' ? 4 : 1;                    // first pass: 1 day, or 4 if easy
  return Math.max(p.ivl + 1, Math.round(p.ivl * p.ease * (grade === 'easy' ? 1.3 : 1)));
}
function schedule(p, grade) {
  const now = Date.now();
  if (grade === 'again') { if (p.reps) p.lapses++; p.ease = Math.max(1.3, p.ease - 0.2); p.ivl = 0; p.due = now + MIN_MS; }
  else { p.ivl = nextIvl(p, grade); if (grade === 'easy') p.ease += 0.15; p.due = now + p.ivl * DAY_MS; }
  p.reps++;
}
function previewLabel(p, grade) { return grade === 'again' ? '1 min' : fmtIvl(nextIvl(p || NEW_REC, grade)); }
function deckStats(deck) {
  const now = Date.now(); const s = { total: deck.cards.length, learned: 0, mastered: 0, fresh: 0, due: 0, next: Infinity };
  deck.cards.forEach((c, i) => {
    const p = prog(deck, i);
    if (!p) { s.fresh++; return; }
    if (p.ivl >= 1) s.learned++;
    if (p.ivl >= 21) s.mastered++;
    if (p.due <= now) s.due++; else s.next = Math.min(s.next, p.due);
  });
  s.ready = s.due + s.fresh;
  return s;
}
function forecast(deck) {      // cards falling due on each of the next 7 calendar days (index 0 = later today)
  const keys = [0, 1, 2, 3, 4, 5, 6].map((k) => dayKey(k)), counts = keys.map(() => 0), now = Date.now();
  deck.cards.forEach((c, i) => {
    const p = prog(deck, i), k = p ? keys.indexOf(dayKey((p.due - now) / DAY_MS)) : -1;
    if (k >= 0) counts[k]++;
  });
  return counts;
}
function totals() {
  const t = { due: 0, fresh: 0, ready: 0 };
  DECKS.forEach((d) => { const s = deckStats(d); t.due += s.due; t.fresh += s.fresh; t.ready += s.ready; });
  return t;
}
function bestDeck() {       // the deck with the most cards waiting; none -> study ahead in the first deck
  let best = null, most = 0;
  DECKS.forEach((d) => { const s = deckStats(d); if (s.ready > most) { most = s.ready; best = d; } });
  return best ? { deck: best, ahead: false } : { deck: DECKS[0], ahead: true };
}
// Due cards (most overdue first), then new ones. "Study ahead" takes the soonest future cards.
function buildQueue(deck, ahead) {
  const now = Date.now(), due = [], fresh = [], later = [];
  deck.cards.forEach((c, i) => { const p = prog(deck, i); if (!p) fresh.push(i); else if (p.due <= now) due.push(i); else later.push(i); });
  due.sort((a, b) => prog(deck, a).due - prog(deck, b).due);
  later.sort((a, b) => prog(deck, a).due - prog(deck, b).due);
  return (ahead ? later : due.concat(fresh)).slice(0, prefs.size);
}

// ===== SESSION FLOW =====
function startSession(deck, ahead) {
  Object.assign(study, { deck, queue: buildQueue(deck, ahead), done: 0, first: {}, counts: { again: 0, good: 0, easy: 0 },
    t0: Date.now(), flipped: false, busy: false, lastGrade: null });
  study.total = study.queue.length; study.empty = !study.total;
  Object.assign(fx, { flip: 0, x: 0, y: 0, rot: 0, shift: 0 });
  const here = K.sceneName === 'study';                // "Study ahead" re-deals inside the study screen
  ui.dragId = null; ui.dealAt = K.t + (here ? 0 : 0.25);
  if (!here) K.go('study', 'slide');
}
function flipCard() {
  if (study.busy) return;
  study.flipped = !study.flipped;
  if (study.flipped) ui.flipAt = K.t; else ui.frontAt = K.t;
  if (ui.flipTw) ui.flipTw.stop();
  // inOutBack: a small squeeze before the turn, edge-on half way through (so the eye sees the turn),
  // then a touch too far and back, like real card stock settling.
  ui.flipTw = K.tween(fx, { flip: study.flipped ? 1 : 0 }, 540, { ease: 'inOutBack' });
  K.sfx('whoosh', { vol: 0.6 });
}
function gradeCard(grade) {
  if (study.busy || !study.queue.length) return;
  study.busy = true; ui.dragId = null; study.lastGrade = grade; ui.frontAt = K.t;
  const idx = study.queue[0], id = cardId(study.deck, idx);
  const p = progress[id] || (progress[id] = Object.assign({}, NEW_REC));
  const label = previewLabel(p, grade);
  schedule(p, grade);
  if (study.first[id] == null) study.first[id] = grade;              // accuracy counts the first answer only
  study.counts[grade]++;
  stats.days[dayKey(0)] = (stats.days[dayKey(0)] || 0) + 1;
  saveAll();
  // Motion: the card is thrown toward its answer while the stack rises behind it.
  const dir = grade === 'again' ? -1 : 1;
  K.tween(fx, { x: dir * K.W * 1.3, y: fx.y + (grade === 'easy' ? -K.H * 0.3 : 70), rot: dir * 0.55 }, 420, { ease: 'outCubic', onDone: nextCard });
  ui.shiftTw = K.tween(fx, { shift: 1 }, 460, { ease: 'outBack' });
  // Sound + visible feedback: a chip with the new interval pops up over the stack (drawGradePill).
  K.sfx('whoosh', { vol: 0.7 });
  K.sfx(grade === 'again' ? 'back' : grade === 'easy' ? 'coin' : 'select');
  const g = GRADES.find((o) => o.id === grade);
  ui.pill = { text: grade === 'again' ? 'Back in a few cards' : 'Next review in ' + label, col: g.col, icon: grade === 'again' ? 'refresh' : 'check', t0: K.t };
}
function nextCard() {
  const idx = study.queue.shift();
  if (study.lastGrade === 'again') study.queue.splice(Math.min(REQUEUE_GAP, study.queue.length), 0, idx);
  else study.done++;
  if (ui.shiftTw) ui.shiftTw.stop();
  if (ui.flipTw) ui.flipTw.stop();
  Object.assign(fx, { flip: 0, x: 0, y: 0, rot: 0, shift: 0 });      // the risen card IS the new top card
  study.flipped = false; study.busy = false;
  if (!study.queue.length) finishSession(false);
}
function closeSession() {
  if (study.busy) return;              // WHY: a card in flight would finish the session again on landing
  if (Object.keys(study.first).length) finishSession(true); else goHome();
}
function goHome() { K.go('decks', 'back'); }
function finishSession(partial) {
  const ids = Object.keys(study.first), right = ids.filter((id) => study.first[id] !== 'again').length;
  const acc = ids.length ? right / ids.length : 0, st = deckStats(study.deck);
  sum = { deck: study.deck, partial, cards: ids.length, acc, secs: (Date.now() - study.t0) / 1000, counts: Object.assign({}, study.counts),
    streakUp: bumpStreak(), left: st.ready, next: st.next, win: !partial && acc >= WIN_AT, t0: K.t };   // t0: its entrance clock
  saveAll();
  ui.streakPopAt = 0; K.go('summary', 'up');
  after(480, celebrate);
}
function bumpStreak() {      // once a day: yesterday -> +1, a gap -> back to 1
  const today = dayKey(0);
  if (stats.last === today) return false;
  stats.streak = stats.last === dayKey(-1) ? stats.streak + 1 : 1;
  stats.best = Math.max(stats.best, stats.streak); stats.last = today;
  return true;
}
function celebrate() {
  if (sum.win) {
    K.burst(K.W / 2, K.safe.top + 40, { n: 80, shape: 'confetti', colors: [INK, AGAIN_COL, GOOD_COL, FLAME, '#f2c14e'], speed: 560, gravity: 900, angle: Math.PI / 2, spread: 2.6 });
    K.sfx('win');
  } else K.sfx('success');
  if (!sum.streakUp) return;
  after(750, () => {
    const f = ui.flamePos; if (!f) return;
    flameSpring.kick(9);
    K.ring(f.x, f.y, { color: FLAME, r1: 70 });
    K.burst(f.x, f.y, { n: 18, shape: 'star', colors: [FLAME, '#f2c14e'], speed: 260, gravity: 240 });
    ui.streakPopAt = K.t;                     // the '+1' chip beside the title springs in
    K.sfx('coin');
  });
}
function resetProgress() {
  progress = {}; stats = { streak: 0, best: stats.best, last: null, days: {} };
  saveAll(); ui.resetArmed = 0;               // the sheet closes itself (close() in drawSettings)
  K.toast('Progress reset', { tone: 'warn', icon: 'refresh' }); K.sfx('back');
}

// ===== SETUP + FRAME =====
function setup() {
  K.setup({ mode: 'light', accent: INK, bg: '#f1ebe0', surface: PAPER, surface2: '#f7f1e6', surface3: '#e9e0cf',
    text: '#1d1b18', text2: 'rgba(29,27,24,0.64)', text3: 'rgba(29,27,24,0.42)', line: 'rgba(59,44,20,0.10)',
    good: GOOD_COL, bad: AGAIN_COL, warn: '#d9822b' });
  loadAll();
  K.scene('decks', drawDecks);
  K.scene('study', drawStudy);
  K.scene('summary', drawSummary);
  syncDecks();
}
function draw() { K.render(); }

// ===== DECKS SCREEN =====
function homeHeight() { return (ui.syncError ? 64 : 0) + TODAY_H + 48 + DECKS.length * (DECK_H + 12) - 12 + 48 + WEEK_H + 32; }
function drawDecks() {
  paperBackdrop();
  const top = K.navBar.top(true), docH = top + homeHeight() + K.safe.bottom;   // content top is known before the bar draws
  ui.scrollY = K.scroll('home', 0, 0, K.W, K.H, docH);     // an open sheet is modal: the page cannot be dragged under it
  const barH = K.navBar.barH || K.safe.top + 50;           // barH is set once the bar has drawn (first frame: its value)
  let y = top - ui.scrollY;
  // Scrolled content is clipped below the nav bar: kit hit tests (K.button, K.tapIn, K.holdIn) only see taps inside the clip.
  K.clip(0, barH, K.W, K.H - barH, () => {
    if (K.t < ui.readyAt) drawHomeSkeleton(y);
    else {
      if (ui.syncError) y = drawSyncBanner(y);
      y = drawTodayCard(y, 0);
      y = drawDeckList(y, 1);
      drawWeekCard(y, 1 + DECKS.length);
    }
  });
  const sub = K.fmt.date(Date.now(), { weekday: 'long', month: 'long', day: 'numeric' });
  if (K.navBar(APP_NAME, ui.scrollY, { sub, right: { id: 'settings', icon: 'settings' } }) === 'settings') ui.sheet = true;
  // Sheets LAST. An open sheet is modal by itself; Done and Reset close it with close() (drawSettings).
  ui.sheet = K.sheet('settings', ui.sheet, SHEET_H + K.safe.bottom, drawSettings);
}
