// ===== STACK: slots, deal-in, flip, drag, fly-off =====
function slotGeom(L, slot) {   // slot 0 = top card; bottom edges step down SLOT_DROP px per slot
  const sc = 1 - slot * SLOT_SCALE;
  return { y: L.cy + slot * SLOT_DROP + (L.h / 2) * (1 - sc), sc };
}
function dealIn(slot) {        // entrance: the back cards land first, then the top card
