}
function drawStack(L) {
  const q = study.queue, pull = clamp01(Math.abs(fx.x) / (K.W * 0.6));
  const shift = Math.max(fx.shift, pull * 0.35);     // the stack leans in while you drag
  for (let s = 3; s >= 1; s--) {                     // back to front
    if (q[s] == null) continue;
    const alpha = s === 3 ? fx.shift : 1;            // a 4th card fades in at the back as the stack moves up
    drawWaitingCard(L, q[s], s - shift, s === 1 ? fx.shift : 0, alpha, dealIn(s));
  }
  if (q[0] != null) drawTopCard(L, q[0], dealIn(0));
}
function drawWaitingCard(L, idx, slot, contentA, alpha, d) {
  if (alpha <= 0.01) return;
  const g = slotGeom(L, slot);
  withAlpha(alpha * clamp01(d * 1.5), () => {
    push(); translate(L.cx, g.y + (1 - d) * 90); scale(g.sc);
    drawPaper(L.w, L.h, K.mix(PAPER, PAPER_BACK, clamp01(slot / 2)), 1);
    if (contentA > 0.01) drawFace(study.deck, idx, 'front', L.w, L.h, contentA);   // the rising card's words fade in
    pop();
  });
}
function drawTopCard(L, idx, d) {
  const turn = fx.flip * Math.PI;                             // 0 = front up, PI = back up
  const sx = Math.max(0.002, Math.abs(Math.cos(turn)));        // WHY: |cos| on scale-x fakes a 3D turn on a flat canvas
  const lift = Math.sin(Math.min(Math.PI, Math.max(0, turn))); // 0 at rest, 1 when edge-on
  const away = clamp01(Math.abs(fx.x) / (K.W * 0.9));
  const cx = L.cx + fx.x, cy = L.cy + fx.y - lift * 18 + (1 - d) * 90, grow = 1 + lift * 0.05;
  groundShadow(L.cx + fx.x * 0.85, L.cy + L.h / 2 + 4 + (1 - d) * 90, L.w, lift, (1 - away) * clamp01(d));
  withAlpha(clamp01(d * 1.5), () => {
    push(); translate(cx, cy); rotate(fx.rot); scale(sx * grow, grow);
    drawPaper(L.w, L.h, PAPER, 2);
    drawFace(study.deck, idx, fx.flip < 0.5 ? 'front' : 'back', L.w, L.h, 1);
    if (lift > 0.01) K.rect(-L.w / 2, -L.h / 2, L.w, L.h, { r: CARD_R, fill: K.alpha(SHADOW_INK, 0.18 * lift) });   // the turning face darkens
    drawStamp(L);
    pop();
  });
  K.registerControl('card', L.cx - L.w / 2, L.cy - L.h / 2, L.w, L.h);
}
// A soft ellipse under the card: it spreads and fades as the card lifts (the "shadow change").
function groundShadow(x, y, w, lift, a) {
  if (a <= 0.01) return;
  push(); translate(x, y + lift * 10); scale(1, 0.16);
  K.glow(0, 0, w * (0.62 + lift * 0.2), SHADOW_INK, (0.34 - lift * 0.16) * a);
  pop();
}
function drawPaper(w, h, fill, elev, plain) {    // plain = no ruled lines (for a message card)
  const x = -w / 2, y = -h / 2;
  K.rect(x, y, w, h, { r: CARD_R, fill, elev, stroke: K.alpha(SHADOW_INK, 0.08) });
  K.line(x + 1, y + 60, x + w - 1, y + 60, K.alpha(MARGIN_RED, 0.55), 1.5);
  if (!plain) for (let k = 1; k <= ruleCount(h); k++) K.line(x + 16, ruleY(h, k), x + w - 16, ruleY(h, k), K.alpha(RULE, 0.5), 1);
}
// Words are written ON the ruled lines, like ink on an index card (never through them).
function ruleY(h, k) { return -h / 2 + 60 + RULE_GAP * k; }
function ruleCount(h) { return Math.floor((h - 84) / RULE_GAP); }
function writeLines(lines, k0, h, role, col, size) {
  lines.forEach((ln, i) => K.text(ln, 0, ruleY(h, k0 + i) - 6, role, col, { align: 'center', size }));
}
// Short words get largeTitle, sentences title, code the mono 'num' role; wrapped to the card width.
function fitText(str, maxW, mono) {
  const role = mono ? 'num' : str.length <= 12 ? 'largeTitle' : 'title';
  const size = mono ? 22 : role === 'largeTitle' ? 36 : 28;
  return { role, size, lines: K.wrap(str, maxW, role, { size }).slice(0, 3) };
}
function drawFace(deck, idx, side, w, h, a) {
  const c = deck.cards[idx], x = -w / 2, y = -h / 2, p = prog(deck, idx), front = side === 'front';
  const n = ruleCount(h), mid = Math.floor((n + 1) / 2);      // the rule at (or just above) the middle: the optical centre
  withAlpha(a, () => {
