    K.text((idx + 1) + ' / ' + deck.cards.length, x + w - 20, y + 38, 'caption', K.C.text3, { align: 'right' });
    if (front) {
      const t = fitText(c[0], w - 56, false);
      writeLines(t.lines, mid - Math.floor((t.lines.length - 1) / 2), h, t.role, K.C.text, t.size);
      K.icon('refresh', -38, ruleY(h, n) - 11, 14, K.C.text3);
      K.text('Tap to flip', -26, ruleY(h, n) - 6, 'footnote', K.C.text3);
    } else {
      const t = fitText(c[1], w - 56, !!deck.mono);             // the answer ends on the line above the middle
