  push(); translate(know ? -L.w / 2 + 84 : L.w / 2 - 84, -L.h / 2 + 108); rotate(know ? -0.2 : 0.2);
  K.rect(-62, -25, 124, 50, { r: 10, fill: K.alpha(PAPER, 0.9 * a), stroke: K.alpha(col, a), sw: 3 });
  K.text(know ? 'KNOW' : 'AGAIN', 0, 1, 'title3', col, { align: 'center', base: 'middle', weight: 800, alpha: a });
