function cardInput(L) {
  if (study.busy || !study.queue.length) return;
  const x = L.cx - L.w / 2, y = L.cy - L.h / 2;
  let p = ui.dragId != null ? K.pointers.find((q) => q.id === ui.dragId) : null;
  if (ui.dragId != null && !p) { ui.dragId = null; releaseCard(); return; }      // the finger lifted
  if (!p) {
    const q = K.holdIn(x, y, L.w, L.h);
    // WHY: claim the finger only once it moves sideways, so a still tap stays a tap (flip).
    if (q && Math.abs(q.x - q.sx) > 10 && Math.abs(q.x - q.sx) > Math.abs(q.y - q.sy)) { q.claimed = 'card'; ui.dragId = q.id; p = q; K.sfx('tick', { vol: 0.4 }); }
  }
  if (p) {
    const nx = p.x - p.sx;
    ui.dragVx = K.approach(ui.dragVx, (nx - fx.x) / Math.max(K.dt, 0.001), 20);
    fx.x = nx; fx.y = (p.y - p.sy) * 0.3; fx.rot = nx * 0.0012;
    return;
  }
  fx.x = K.approach(fx.x, 0, 14); fx.y = K.approach(fx.y, 0, 14); fx.rot = K.approach(fx.rot, 0, 14);   // spring home
  if (K.tapIn(x, y, L.w, L.h)) flipCard();
  else if (K.swipe === 'right') gradeCard('good');     // a quick flick the drag code never saw move
  else if (K.swipe === 'left') gradeCard('again');
  for (const key of K.pressedKeys) {                   // desktop testing: space flips, arrows grade
    if (key === ' ') flipCard(); else if (key === 'ArrowRight') gradeCard('good'); else if (key === 'ArrowLeft') gradeCard('again');
  }
}
function releaseCard() {
  const fling = Math.abs(ui.dragVx) > 900;
  if (fx.x > K.W * 0.25 || (fling && ui.dragVx > 0 && fx.x > 30)) gradeCard('good');
  else if (fx.x < -K.W * 0.25 || (fling && ui.dragVx < 0 && fx.x < -30)) gradeCard('again');
  else K.sfx('tick', { vol: 0.4 });                    // not far enough: it springs back
