    const pl = clamp01(-fx.x / 90), pr = clamp01(fx.x / 90);             // the side you drag toward lights up
    const e = Math.min(K.stagger(2, 55, 440), K.since(ui.frontAt, 0, 350)), r = rise(e), hy = L.hintY + r;
    K.icon('chevronLeft', SIDE + 8, hy - 5, 16, AGAIN_COL, { weight: 2.6, alpha: e * (0.55 + 0.45 * pl) });
    K.text('Again', SIDE + 20, hy, 'subhead', AGAIN_COL, { weight: 600, alpha: e * (0.55 + 0.45 * pl) });
    K.text('swipe or tap the card', K.W / 2, hy, 'footnote', K.C.text3, { align: 'center', alpha: e });
    K.text('Know', K.W - SIDE - 20, hy, 'subhead', GOOD_COL, { align: 'right', weight: 600, alpha: e * (0.55 + 0.45 * pr) });
    K.icon('chevronRight', K.W - SIDE - 8, hy - 5, 16, GOOD_COL, { weight: 2.6, alpha: e * (0.55 + 0.45 * pr) });
    if (K.button('show', SIDE, L.btnY + r, K.W - SIDE * 2, 52, 'Show answer', { icon: 'eye', sfx: false, alpha: e })) flipCard();
    return;
  }
  // Grade buttons rise in one after another; the caption above each is the next review interval.
  const gw = (K.W - SIDE * 2 - 20) / 3, p = prog(study.deck, study.queue[0]);
  GRADES.forEach((g, i) => {
    const e = K.since(ui.flipAt, i * 60, 400, 'outBack'), bx = SIDE + i * (gw + 10), by = L.btnY + (1 - e) * 26;
    K.text(previewLabel(p, g.id), bx + gw / 2, by - 10, 'caption', K.C.text3, { align: 'center', alpha: clamp01(e) });
    if (K.button(g.id, bx, by, gw, 52, g.label, { color: g.col, sfx: false, alpha: clamp01(e) })) gradeCard(g.id);
  });
}
function drawCaughtUp(L) {       // EMPTY: nothing due in this deck. The card sits where the stack would.
  const st = deckStats(study.deck), e = K.stagger(1, 55, 440), deck = study.deck, w = L.w;
  const ch = Math.min(L.h, L.btnY - 60 - 24 - L.cardTop), top = -ch / 2;   // stops above the two buttons
  withAlpha(e, () => {
    push(); translate(L.cx, L.cardTop + ch / 2 + rise(e));
    groundShadow(0, ch / 2 + 4, w, 0, 1);
    drawPaper(w, ch, PAPER, 2, true);
    K.text(deck.name.toUpperCase(), -w / 2 + 20, top + 38, 'label', K.C.text3);
    K.text(st.learned + ' / ' + st.total, w / 2 - 20, top + 38, 'caption', K.C.text3, { align: 'right' });
    K.empty(0, top + 76, 'check', 'All caught up', 'Next review ' + fmtDue(st.next) + '. Come back then, or study ahead now.');
    if (ch >= 476) drawForecast(deck, -w / 2 + 24, top + 288, w - 48, e);   // skipped on short phones
    K.progressBar(-w / 2 + 40, ch / 2 - 58, w - 80, 6, (st.learned / st.total) * e, { color: deck.hue });
    K.text(st.learned + ' learned, ' + st.mastered + ' mastered', 0, ch / 2 - 26, 'footnote', K.C.text3, { align: 'center' });
    pop();
  });
  if (K.button('ahead', SIDE, L.btnY - 60, K.W - SIDE * 2, 52, 'Study ahead', { icon: 'bolt' })) startSession(deck, true);
  if (K.button('backDecks', SIDE, L.btnY, K.W - SIDE * 2, 52, 'Back to decks', { style: 'secondary', sfx: 'back' })) goHome();
}
function drawForecast(deck, x, y, w, e) {     // COMING UP: how many reviews land on each of the next 7 days
  const vals = forecast(deck), labels = vals.map((v, k) => dayLetter(k));
  K.text('COMING UP', x, y, 'label', K.C.text3);
  K.text(plural(vals.reduce((a, b) => a + b, 0), 'card') + ' this week', x + w, y, 'caption', K.C.text3, { align: 'right' });
  K.bars(vals, x, y + 16, w, 72, { labels, highlight: 0, color: deck.hue, t: e });
}

// ===== SUMMARY SCREEN =====
function drawSummary() {
  paperBackdrop();
  if (!sum) return;
  const x = SIDE, w = K.W - SIDE * 2, e0 = K.stagger(0, 55, 440), top = K.safe.top, r = rise(e0);
  const title = sum.partial ? 'Good stopping point' : sum.win ? 'Brilliant session' : sum.acc >= 0.35 ? 'Solid work' : 'Tough one, keep going';
  K.text(sum.partial ? 'SESSION SAVED' : 'SESSION COMPLETE', K.W / 2, top + 52 + r, 'label', INK, { align: 'center', alpha: e0 });
  K.text(title, K.W / 2, top + 88 + r, 'title', K.C.text, { align: 'center', alpha: e0 });
  K.text(sum.deck.name + ', ' + plural(sum.cards, 'card') + ' in ' + fmtSpan(sum.secs), K.W / 2, top + 114 + r, 'subhead', K.C.text2, { align: 'center', alpha: e0 });
  // Flexible layout: the score (136) and streak (140) cards are fixed; the answers card takes the room
  // the footer leaves, so there is no dead band. Gaps are 24 (16 on short phones); no room -> drop it.
  const by = K.H - K.safe.bottom - 20 - 52, footTop = sum.left > 0 ? by - 60 : by;
  const room = footTop - 24 - (top + 136), gap = room >= 460 ? 24 : 16, ansH = room - 136 - 140 - gap * 2;
  let y = top + 136;
  y = drawScoreCard(x, y, w, 1) + gap;
  if (ansH >= 120) y = drawAnswersCard(x, y, w, Math.min(ansH, 280), 2) + gap;
  drawStreakCard(x, y, w, 3);
  const e4 = K.stagger(4, 55, 440);                 // controls fade in with { alpha } (below 0.3 they are inert)
  if (sum.left > 0 && K.button('more', x, footTop, w, 50, 'Keep studying, ' + sum.left + ' left', { style: 'secondary', icon: 'refresh', alpha: e4 })) startSession(sum.deck, false);
  if (K.button('done', x, by, w, 52, 'Done', { icon: 'check', alpha: e4 })) goHome();
}
function drawScoreCard(x, y, w, i) {
  const e = K.stagger(i, 55, 440), h = 136, roll = K.since(sum.t0, 350, 900);
  withAlpha(e, () => {
    push(); translate(0, rise(e));
    K.card(x, y, w, h, { fill: PAPER });
    const rcx = x + 72, rcy = y + h / 2;
    K.progressRing(rcx, rcy, 48, sum.acc * roll, { width: 10, color: [GOOD_COL, '#79c49a'] });
    K.num(Math.round(sum.acc * 100 * roll) + '%', rcx, rcy - 4, 'title2', K.C.text, { align: 'center', base: 'middle' });
    K.text('CORRECT', rcx, rcy + 17, 'label', K.C.text3, { align: 'center', base: 'middle' });
    const next = sum.left ? sum.left + ' ready' : fmtDue(sum.next);
    const rows = [['check', 'Reviewed', plural(sum.cards, 'card')], ['clock', 'Time', K.fmt.clock(sum.secs * 1000)], ['calendar', 'Up next', next]];
    rows.forEach((r, k) => {
      const ry = y + 34 + k * 34, lx = x + 144;
      if (k) K.line(lx, ry - 17, x + w - 16, ry - 17, K.C.line, 1);
      K.icon(r[0], lx + 8, ry, 16, INK);
      K.text(r[1], lx + 26, ry + 0.5, 'subhead', K.C.text2, { base: 'middle' });
      K.text(r[2], x + w - 16, ry + 0.5, 'subhead', K.C.text, { align: 'right', base: 'middle', weight: 600 });
    });
    pop();
  });
  return y + h;
}
function drawAnswersCard(x, y, w, h, i) {
  const e = K.stagger(i, 55, 440), bh = h - 102;
  withAlpha(e, () => {
    push(); translate(0, rise(e));
    K.card(x, y, w, h, { fill: PAPER });
    K.text('HOW YOU ANSWERED', x + 16, y + 30, 'label', K.C.text3);
    // ONE K.bars call: a colour per grade; gap = column - bar puts 52 px bars in 3 centred columns. The counts are ours:
    // K.bars' values:true labels are small text2 captions, and a count reads best as a headline in its grade's colour.
    const col = (w - 32) / 3, bw = 52, vals = GRADES.map((g) => sum.counts[g.id]), max = Math.max(1, ...vals), grow = K.since(sum.t0, 450, 700);
    K.bars(vals, x + 16 + (col - bw) / 2, y + 58, col * 2 + bw, bh, { colors: GRADES.map((g) => g.col), labels: GRADES.map((g) => g.label),
      max, gap: col - bw, r: 8, t: grow });
    GRADES.forEach((g, k) => {                                  // the same bar top K.bars uses; a 0 gets a 3 px baseline (K.bars draws none)
      const v = vals[k], cx = x + 16 + col * k + col / 2, top = y + 58 + bh - Math.max(3, (v / max) * bh * grow);
      if (!v) K.rect(cx - bw / 2, top, bw, 3, { r: 1.5, fill: K.alpha(g.col, 0.85) });
      K.num(String(v), cx, top - 8, 'headline', g.col, { align: 'center' });
    });
    pop();
  });
  return y + h;
}
function drawStreakCard(x, y, w, i) {
  const e = K.stagger(i, 55, 440), h = 140;
  withAlpha(e, () => {
    push(); translate(0, rise(e));
    K.card(x, y, w, h, { fill: PAPER });
    const fx0 = x + 42, fy0 = y + 44;
    ui.flamePos = { x: fx0, y: fy0 + rise(e) };
    K.glow(fx0, fy0, 46, FLAME, 0.22);
    push(); translate(fx0, fy0); scale(flameSpring.v);
    K.circle(0, 0, 24, { fill: K.alpha(FLAME, 0.16) });
    K.icon('flame', 0, 0, 28, FLAME, { weight: 2.2 });
    pop();
    const tw = K.text(stats.streak + '-day streak', x + 80, y + 42, 'title3', K.C.text);
    const chipK = K.springTo('streakChip', ui.streakPopAt && K.t > ui.streakPopAt ? 1 : 0, { k: 320, d: 14 });
    if (chipK > 0.02) {
      push(); translate(x + 92 + tw, y + 36); scale(chipK); K.chip(-4, -12, '+1 day', { color: FLAME, icon: 'flame', filled: true }); pop();
    }
    K.text(sum.streakUp ? 'Best ' + plural(stats.best, 'day') + '. See you tomorrow!' : 'Already counted today. Best ' + plural(stats.best, 'day') + '.', x + 80, y + 62, 'footnote', K.C.text2);
    weekStrip(x + 16, y + 104, w - 32);
    pop();
  });
}
function weekStrip(x, cy, w) {     // 7 day discs, oldest on the left; today bounces with the flame
  const step = w / 7;
  for (let k = 0; k < 7; k++) {
    const off = k - 6, on = (stats.days[dayKey(off)] || 0) > 0, cx = x + step * (k + 0.5), sc = off === 0 ? flameSpring.v : 1;
    if (off === 0) K.circle(cx, cy, 19, { fill: 'none', stroke: K.alpha(FLAME, 0.45), sw: 2 });
    K.circle(cx, cy, 15 * sc, { fill: on ? FLAME : K.C.surface3 });
    K.text(dayLetter(off), cx, cy + 0.5, 'caption', on ? '#ffffff' : K.C.text3, { align: 'center', base: 'middle', weight: 700 });
  }
}
